<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
html,body{height:100%;width:100%;font-family:'DM Sans',sans-serif;color:#1c1c2e;overflow:hidden;}

body{
  background:
    radial-gradient(ellipse 80% 55% at 0% 0%,   rgba(255,200,180,.55) 0%,transparent 55%),
    radial-gradient(ellipse 65% 65% at 100% 0%,  rgba(180,210,245,.50) 0%,transparent 55%),
    radial-gradient(ellipse 60% 60% at 95% 100%, rgba(200,170,235,.45) 0%,transparent 55%),
    radial-gradient(ellipse 65% 50% at 0%  100%, rgba(255,225,160,.42) 0%,transparent 55%),
    radial-gradient(ellipse 50% 50% at 50%  50%, rgba(170,230,215,.25) 0%,transparent 60%),
    #f6f2ff;
  animation:bgP 14s ease-in-out infinite alternate;
}
@keyframes bgP{
  0%  {filter:hue-rotate(0deg)  saturate(1)    brightness(1);}
  50% {filter:hue-rotate(7deg)  saturate(1.05) brightness(1.01);}
  100%{filter:hue-rotate(-5deg) saturate(1)    brightness(1);}
}

/* ORBES */
.orbs{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:0;}
.orb{position:absolute;border-radius:50%;filter:blur(65px);animation:dO ease-in-out infinite alternate;}
.o1{width:420px;height:420px;background:radial-gradient(circle,rgba(255,160,120,.30),transparent);top:-100px;left:-80px;animation-duration:16s;}
.o2{width:360px;height:360px;background:radial-gradient(circle,rgba(160,200,245,.32),transparent);top:-50px;right:-70px;animation-duration:18s;animation-delay:-5s;}
.o3{width:320px;height:320px;background:radial-gradient(circle,rgba(200,160,235,.28),transparent);bottom:-70px;right:-50px;animation-duration:14s;animation-delay:-8s;}
.o4{width:290px;height:290px;background:radial-gradient(circle,rgba(255,220,130,.26),transparent);bottom:-50px;left:-30px;animation-duration:17s;animation-delay:-3s;}
.o5{width:240px;height:240px;background:radial-gradient(circle,rgba(150,220,195,.24),transparent);top:35%;left:33%;animation-duration:12s;animation-delay:-6s;}
@keyframes dO{from{transform:translate(0,0)scale(1);}to{transform:translate(22px,-18px)scale(1.07);}}

/* DOTS */
.dots{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:1;}
.fd{position:absolute;border-radius:50%;animation:fD linear infinite;opacity:0;}
@keyframes fD{
  0%  {transform:translateY(105vh)scale(.6);opacity:0;}
  8%  {opacity:.85;} 92%{opacity:.80;}
  100%{transform:translateY(-8vh)scale(1.1);opacity:0;}
}

/* ═══════════════════════
   BIENVENIDA
═══════════════════════ */
.ws{
  position:fixed;inset:0;z-index:100;
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:1.5rem;
  background:
    radial-gradient(ellipse 80% 55% at 0% 0%,   rgba(255,200,180,.55) 0%,transparent 55%),
    radial-gradient(ellipse 65% 65% at 100% 0%,  rgba(180,210,245,.50) 0%,transparent 55%),
    radial-gradient(ellipse 65% 50% at 0%  100%, rgba(255,225,160,.42) 0%,transparent 55%),
    #f6f2ff;
  opacity:1;visibility:visible;pointer-events:all;
  transition:opacity .55s ease,visibility .55s ease;
}
.ws.gone{opacity:0;visibility:hidden;pointer-events:none;}

.wi{display:flex;flex-direction:column;align-items:center;max-width:450px;width:100%;}
.w-logo{width:118px;margin-bottom:.85rem;filter:drop-shadow(0 6px 24px rgba(80,120,80,.18));animation:fU .8s ease both;}
.w-title{font-family:'Cormorant Garamond',serif;font-size:clamp(1.75rem,5vw,2.8rem);font-weight:400;color:#1c1c2e;text-align:center;margin-bottom:.25rem;line-height:1.15;animation:fU .8s ease .08s both;}
.w-title em{font-style:italic;background:linear-gradient(110deg,#c06090,#9060d0 45%,#4090c8);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}
.w-sub{font-size:.78rem;font-weight:300;color:#6b6880;text-align:center;margin-bottom:1.4rem;animation:fU .8s ease .14s both;}
.w-bar{width:min(250px,72vw);height:3px;border-radius:100px;background:linear-gradient(90deg,#f4a261,#e07090,#c77dcc,#7090d8,#60b8a8,#88c878,#f4a261);background-size:200% 100%;animation:sF 5s linear infinite,fU .8s ease .18s both;margin-bottom:1.6rem;}
@keyframes sF{0%{background-position:0%}100%{background-position:200%}}
.w-q{font-family:'Cormorant Garamond',serif;font-size:1.05rem;font-weight:500;color:#3a3050;text-align:center;margin-bottom:.95rem;animation:fU .8s ease .24s both;}
.w-roles{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%;animation:fU .8s ease .3s both;}
.wrc{display:flex;flex-direction:column;align-items:center;gap:7px;padding:1.3rem .85rem;background:rgba(255,255,255,.70);border:1.5px solid rgba(140,100,190,.18);border-radius:16px;cursor:pointer;transition:all .22s;backdrop-filter:blur(16px);box-shadow:0 4px 20px rgba(100,80,160,.08);position:relative;overflow:hidden;}
.wrc::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;border-radius:16px 16px 0 0;opacity:0;transition:opacity .22s;}
.wrc.s::before{background:linear-gradient(90deg,#7090d8,#60b8a8);}
.wrc.a::before{background:linear-gradient(90deg,#c77dcc,#e07090);}
.wrc:hover{transform:translateY(-3px);box-shadow:0 10px 30px rgba(100,80,160,.14);border-color:rgba(140,100,190,.3);}
.wrc:hover::before{opacity:1;}
.wri{width:48px;height:48px;border-radius:13px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;}
.wrc.s .wri{background:rgba(112,144,216,.14);}.wrc.a .wri{background:rgba(199,125,204,.14);}
.w-name{font-family:'Cormorant Garamond',serif;font-size:1.06rem;font-weight:500;color:#1c1c2e;}
.w-desc{font-size:.68rem;font-weight:300;color:#8a8098;text-align:center;line-height:1.5;}
.w-btn{font-size:.63rem;font-weight:700;letter-spacing:.07em;text-transform:uppercase;margin-top:1px;}
.wrc.s .w-btn{color:#3060a8;}.wrc.a .w-btn{color:#9050a0;}

/* ═══════════════════════
   LOGIN PRINCIPAL
═══════════════════════ */
.page{
  position:fixed;inset:0;z-index:50;
  display:grid;
  grid-template-columns:55fr 45fr;
  opacity:0;visibility:hidden;pointer-events:none;
  transition:opacity .55s ease .05s,visibility .55s ease .05s;
}
.page.visible{opacity:1;visibility:visible;pointer-events:all;}

/* ─── IZQUIERDO ─── */
.left{
  display:flex;
  flex-direction:column;
  justify-content:center;
  align-items:flex-start;
  padding:2.5rem 3.5rem 2.5rem 10rem;
  overflow-y:auto;
  position:relative;
}
.left::after{
  content:'';position:absolute;right:0;top:8%;bottom:8%;width:1px;
  background:linear-gradient(to bottom,transparent,rgba(140,100,190,.18),rgba(100,170,210,.14),transparent);
}

/* Ilustración cerebro — más grande */
.l-art{
  margin-bottom:1.6rem;
  filter:drop-shadow(0 10px 28px rgba(100,80,160,.10));
  width:min(420px, 62%);
  height:auto;
}

.l-inst{display:inline-flex;align-items:center;gap:7px;padding:5px 14px;background:rgba(255,255,255,.55);border:1px solid rgba(140,100,190,.18);border-radius:100px;backdrop-filter:blur(10px);font-size:.63rem;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:#6b5490;margin-bottom:.9rem;}
.l-dot{width:6px;height:6px;border-radius:50%;background:linear-gradient(135deg,#e08060,#9060d0);animation:pu 2.8s ease infinite;flex-shrink:0;}
@keyframes pu{0%,100%{opacity:1;transform:scale(1);}50%{opacity:.5;transform:scale(.75);}}
.l-ri{display:inline-flex;align-items:center;gap:6px;padding:5px 13px;border-radius:100px;font-size:.64rem;font-weight:600;margin-bottom:1rem;cursor:pointer;transition:opacity .2s;}
.l-ri:hover{opacity:.7;}
.l-ri.s{background:rgba(112,144,216,.15);color:#3060a8;border:1px solid rgba(112,144,216,.24);}
.l-ri.a{background:rgba(199,125,204,.15);color:#9050a0;border:1px solid rgba(199,125,204,.24);}

/* Heading más grande */
.l-h{
  font-family:'Cormorant Garamond',serif;
  font-size:clamp(2rem,2.8vw,3.4rem);
  font-weight:400;line-height:1.15;color:#1c1c2e;margin-bottom:.85rem;
}
.l-h em{font-style:italic;background:linear-gradient(110deg,#c06090,#9060d0 40%,#4090c8);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}

.l-p{font-size:.88rem;font-weight:300;color:#6b6880;line-height:1.85;max-width:520px;margin-bottom:1.4rem;}
.l-spec{display:flex;flex-direction:column;gap:5px;max-width:520px;margin-bottom:1.4rem;}
.l-sl{font-size:.62rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:#9a90aa;}
.l-sb{height:5px;border-radius:100px;background:linear-gradient(90deg,#f4a261 0%,#e07090 18%,#c77dcc 34%,#7090d8 50%,#60b8a8 66%,#88c878 82%,#f4a261 100%);background-size:200% 100%;animation:sF 6s linear infinite;}
.l-se{display:flex;justify-content:space-between;font-size:.62rem;color:#9a90aa;font-weight:500;}
.l-q{background:rgba(255,255,255,.50);border:1px solid rgba(140,100,190,.14);border-radius:16px;padding:.95rem 1.3rem;max-width:520px;backdrop-filter:blur(14px);position:relative;}
.l-q::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;border-radius:16px 16px 0 0;background:linear-gradient(90deg,#f4a261,#e07090,#c77dcc,#7090d8,#60b8a8);}
.l-qm{font-family:'Cormorant Garamond',serif;font-size:3rem;line-height:.5;color:#c07090;opacity:.25;float:left;margin-right:8px;margin-top:10px;}
.l-qt{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:.9rem;color:#3a3050;line-height:1.65;}
.l-qa{margin-top:.45rem;clear:both;font-size:.63rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#9a90aa;}

/* ─── DERECHO ─── */
.right{
  display:flex;
  align-items:center;
  justify-content:center;
  padding:2rem 3rem 2rem 0.5rem;
}
.card{
  width:100%;max-width:490px;
  background:rgba(255,255,255,.82);
  backdrop-filter:blur(30px);-webkit-backdrop-filter:blur(30px);
  border:1px solid rgba(255,255,255,.92);border-radius:22px;
  padding:2rem 1.9rem 1.7rem;
  box-shadow:0 20px 60px rgba(80,50,130,.12),0 4px 16px rgba(80,50,130,.06),inset 0 1px 0 rgba(255,255,255,.9);
  position:relative;overflow:hidden;
}
.card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg,#f4a261,#e07090,#c77dcc,#7090d8,#60b8a8,#88c878,#f4a261);background-size:200% 100%;animation:sF 5s linear infinite;border-radius:22px 22px 0 0;}

/* Logo encima del formulario — dentro del card */
.card-logo{
  display:flex;justify-content:center;
  margin-bottom:1.2rem;
}
.card-logo img{
  width:100px;height:100px;
  object-fit:contain;border-radius:50%;
  filter:drop-shadow(0 4px 16px rgba(80,130,80,.20));
}

.c-strips{display:flex;gap:4px;margin-bottom:1rem;}
.cs{height:3px;flex:1;border-radius:100px;transition:transform .2s;cursor:default;}
.cs:hover{transform:scaleY(3);}
.cs1{background:#f4a261;}.cs2{background:#e07090;}.cs3{background:#c77dcc;}.cs4{background:#7090d8;}.cs5{background:#60b8a8;}.cs6{background:#88c878;}

.c-title{font-family:'Cormorant Garamond',serif;font-size:1.65rem;font-weight:500;color:#1c1c2e;margin-bottom:.12rem;}
.c-rtag{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:100px;font-size:.63rem;font-weight:600;margin-bottom:.95rem;}
.c-rtag.s{background:rgba(112,144,216,.12);color:#3060a8;border:1px solid rgba(112,144,216,.2);}
.c-rtag.a{background:rgba(199,125,204,.12);color:#9050a0;border:1px solid rgba(199,125,204,.2);}
.c-chg{display:block;font-size:.67rem;color:#9a90aa;margin-bottom:1.1rem;cursor:pointer;text-decoration:none;transition:color .2s;}
.c-chg:hover{color:#9060c0;}.c-chg span{color:#9060c0;font-weight:600;}

/* inputs */
.fg{margin-bottom:.85rem;}
.fg label{display:block;font-size:.65rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#6b6880;margin-bottom:.34rem;}
.iw{position:relative;display:flex;align-items:center;}
.ic{position:absolute;left:13px;color:#9a90aa;opacity:.5;pointer-events:none;transition:opacity .2s,color .2s;}
input[type=text],input[type=password]{
  width:100%;padding:11px 13px 11px 40px;
  border:1.5px solid rgba(140,100,190,.15);border-radius:11px;
  background:rgba(255,255,255,.78);font-family:'DM Sans',sans-serif;
  font-size:.84rem;color:#1c1c2e;outline:none;
  transition:border-color .2s,box-shadow .2s,background .2s;
}
input[type=text]:focus,input[type=password]:focus{border-color:#c77dcc;background:rgba(255,255,255,.97);box-shadow:0 0 0 3px rgba(199,125,204,.12);}
input::placeholder{color:#c0b8d8;}
.iw:focus-within .ic{opacity:1;color:#c77dcc;}
.hint{font-size:.6rem;color:#b0a8c8;margin-top:.22rem;font-style:italic;}
.ep{position:absolute;right:11px;background:none;border:none;color:#9a90aa;opacity:.5;cursor:pointer;padding:4px;transition:opacity .2s;display:flex;align-items:center;}
.ep:hover{opacity:1;}
.fe{display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;flex-wrap:wrap;gap:.3rem;}
.rm{display:flex;align-items:center;gap:6px;font-size:.72rem;color:#8a8098;cursor:pointer;user-select:none;}
input[type=checkbox]{width:14px;height:14px;accent-color:#c77dcc;padding:0;flex-shrink:0;}
.fg2{font-size:.7rem;color:#9060c0;text-decoration:none;font-weight:500;transition:color .2s;}
.fg2:hover{color:#e07090;}
.eb{display:none;background:rgba(220,80,80,.07);border:1px solid rgba(220,80,80,.18);border-radius:10px;padding:9px 12px;font-size:.73rem;color:#a03030;margin-bottom:.8rem;gap:7px;align-items:center;}
.eb.show{display:flex;animation:sk .4s ease;}
@keyframes sk{0%,100%{transform:translateX(0);}20%,60%{transform:translateX(-4px);}40%,80%{transform:translateX(4px);}}
.bs{width:100%;padding:12.5px;border:none;border-radius:12px;background:linear-gradient(135deg,#b070d0 0%,#8090d0 50%,#60a8b8 100%);background-size:200% 100%;background-position:0%;color:white;font-family:'DM Sans',sans-serif;font-size:.86rem;font-weight:600;cursor:pointer;position:relative;overflow:hidden;transition:background-position .5s,transform .15s,box-shadow .2s;box-shadow:0 6px 22px rgba(140,100,200,.28);letter-spacing:.02em;}
.bs:hover{background-position:100%;transform:translateY(-1px);box-shadow:0 10px 28px rgba(140,100,200,.35);}
.bs:active{transform:translateY(0);}
.bt{transition:opacity .2s;}.bs.ld .bt{opacity:0;}
.sp{position:absolute;inset:0;display:none;align-items:center;justify-content:center;}.bs.ld .sp{display:flex;}
.rg{width:18px;height:18px;border:2px solid rgba(255,255,255,.3);border-top-color:white;border-radius:50%;animation:spin .7s linear infinite;}
@keyframes spin{to{transform:rotate(360deg);}}
.cf{display:flex;align-items:center;gap:9px;font-size:.65rem;color:#c0b8d8;margin:.85rem 0 0;}
.cf::before,.cf::after{content:'';flex:1;height:1px;background:rgba(140,100,190,.12);}
.rk{text-align:center;font-size:.73rem;color:#8a8098;margin-top:.5rem;}
.rk a{color:#9060c0;font-weight:600;text-decoration:none;}.rk a:hover{color:#e07090;}

/* mini header móvil */
.mh{display:none;align-items:center;gap:10px;margin-bottom:.9rem;padding-bottom:.85rem;border-bottom:1px solid rgba(140,100,190,.1);}
.mh img{width:36px;height:36px;object-fit:contain;border-radius:9px;}
.mh-n{font-family:'Cormorant Garamond',serif;font-size:.9rem;color:#1c1c2e;font-weight:500;}
.mh-s{font-size:.59rem;color:#9a90aa;}

@keyframes fU{from{opacity:0;transform:translateY(13px);}to{opacity:1;transform:translateY(0);}}

/* ═══ RESPONSIVE ═══ */
@media(max-width:1000px){
  .left{padding:2.5rem 2.5rem 2.5rem 3rem;}
  .right{padding:2rem 2rem 2rem 1rem;}
  .l-art{width:min(250px,40%);}
  .l-h{font-size:clamp(1.8rem,2.5vw,2.8rem);}
}
@media(max-width:780px){
  .page{grid-template-columns:1fr 1fr;}
  .left{padding:2rem 1.5rem 2rem 2rem;}
  .right{padding:2rem 1.5rem 2rem 1rem;}
  .l-q,.l-p{display:none;}
  .l-art{width:180px;}
  .left::after{display:none;}
}
@media(max-width:560px){
  html,body{overflow:auto;height:auto;}
  .ws{overflow-y:auto;}
  .page{position:relative;grid-template-columns:1fr;min-height:100svh;}
  .left{display:none;}
  .right{min-height:100svh;align-items:flex-start;padding:1.5rem 1rem 2rem;}
  .card{max-width:100%;border-radius:18px;}
  .mh{display:flex;}
  .card-logo img{width:60px;height:60px;}
}
@media(max-width:340px){
  .w-roles{grid-template-columns:1fr;}
  .wrc{flex-direction:row;justify-content:flex-start;padding:.85rem;gap:10px;}
  .wri{flex-shrink:0;}
}
</style>
</head>
<body>

<div class="orbs">
  <div class="orb o1"></div><div class="orb o2"></div>
  <div class="orb o3"></div><div class="orb o4"></div><div class="orb o5"></div>
</div>
<div class="dots" id="dots"></div>

<!-- ══ BIENVENIDA ══ -->
<div class="ws" id="ws">
  <div class="wi">
    <img class="w-logo" src="data:image/png;base64," alt="UTN CEPS"/>
    <h1 class="w-title">Bienvenido/a al<br><em>Centro de Atención Psicológica</em></h1>
    <p class="w-sub">CEPS · Universidad Tecnológica del Norte · Opción con Futuro</p>
    <div class="w-bar"></div>
    <p class="w-q">¿Con quién estamos hablando hoy?</p>
    <div class="w-roles">
      <div class="wrc s" onclick="selectRole('usuario')">
        <div class="wri">🎓</div>
        <span class="w-name">Soy Estudiante</span>
        <span class="w-desc">Ingresa con tu matrícula universitaria</span>
        <span class="w-btn">CONTINUAR →</span>
      </div>
      <div class="wrc a" onclick="selectRole('admin')">
        <div class="wri">🩺</div>
        <span class="w-name">Soy Psicóloga</span>
        <span class="w-desc">Ingresa con tu número de empleado</span>
        <span class="w-btn">CONTINUAR →</span>
      </div>
    </div>
  </div>
</div>

<!-- ══ LOGIN ══ -->
<div class="page" id="page">

  <!-- IZQUIERDO — más grande y con mejor espacio -->
  <div class="left">
    <svg class="l-art" viewBox="0 0 280 185" fill="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <radialGradient id="g1" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#ffd080" stop-opacity=".85"/><stop offset="100%" stop-color="#ffb06a" stop-opacity="0"/></radialGradient>
        <radialGradient id="g2" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#e87095" stop-opacity=".8"/><stop offset="100%" stop-color="#f0a0c0" stop-opacity="0"/></radialGradient>
        <radialGradient id="g3" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#b080d8" stop-opacity=".75"/><stop offset="100%" stop-color="#d0b0f0" stop-opacity="0"/></radialGradient>
        <radialGradient id="g4" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#70a0d8" stop-opacity=".75"/><stop offset="100%" stop-color="#a0c8f0" stop-opacity="0"/></radialGradient>
        <radialGradient id="g5" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#60b898" stop-opacity=".72"/><stop offset="100%" stop-color="#90d8b8" stop-opacity="0"/></radialGradient>
        <filter id="bl2"><feGaussianBlur stdDeviation="2"/></filter>
        <filter id="bl4"><feGaussianBlur stdDeviation="4"/></filter>
      </defs>
      <ellipse cx="140" cy="92" rx="130" ry="82" fill="url(#g4)" filter="url(#bl4)" opacity=".5"/>
      <path d="M96 140C70 138 50 120 48 98 46 78 58 62 72 56 68 44 74 32 86 28 94 16 110 14 122 22 128 14 138 10 150 12 162 10 174 18 178 30 190 28 202 36 206 50 218 52 226 64 224 78 230 88 228 104 218 114 212 128 198 138 182 140Z" fill="rgba(255,255,255,.22)" stroke="rgba(140,100,200,.18)" stroke-width="1.5"/>
      <ellipse cx="100" cy="55"  rx="34" ry="22" fill="url(#g1)" filter="url(#bl2)" opacity=".9"  transform="rotate(-10 100 55)"/>
      <ellipse cx="165" cy="50"  rx="30" ry="20" fill="url(#g2)" filter="url(#bl2)" opacity=".85" transform="rotate(8 165 50)"/>
      <ellipse cx="90"  cy="100" rx="32" ry="20" fill="url(#g3)" filter="url(#bl2)" opacity=".8"  transform="rotate(5 90 100)"/>
      <ellipse cx="180" cy="95"  rx="28" ry="18" fill="url(#g4)" filter="url(#bl2)" opacity=".8"  transform="rotate(-8 180 95)"/>
      <ellipse cx="140" cy="120" rx="30" ry="18" fill="url(#g5)" filter="url(#bl2)" opacity=".78"/>
      <path d="M82 65Q100 45 124 42Q148 45 160 60"  stroke="rgba(180,140,220,.45)" stroke-width="2"   fill="none" stroke-linecap="round"/>
      <path d="M80 80Q100 60 130 55Q160 58 178 72"  stroke="rgba(140,180,220,.40)" stroke-width="1.5" fill="none" stroke-linecap="round"/>
      <path d="M85 95Q110 78 140 76Q165 78 182 90"  stroke="rgba(180,140,220,.35)" stroke-width="1.5" fill="none" stroke-linecap="round"/>
      <path d="M90 110Q115 95 140 93Q165 95 178 108" stroke="rgba(100,180,170,.38)" stroke-width="1.5" fill="none" stroke-linecap="round"/>
      <circle cx="108" cy="42"  r="5"   fill="#ffd080" opacity=".8"/>
      <circle cx="96"  cy="58"  r="3.5" fill="#e87095" opacity=".75"/>
      <circle cx="172" cy="42"  r="4.5" fill="#e87095" opacity=".8"/>
      <circle cx="185" cy="60"  r="3"   fill="#ffd080" opacity=".7"/>
      <circle cx="78"  cy="88"  r="4"   fill="#b080d8" opacity=".75"/>
      <circle cx="198" cy="86"  r="3.5" fill="#7090d8" opacity=".75"/>
      <circle cx="142" cy="30"  r="4"   fill="#b080d8" opacity=".72"/>
      <circle cx="130" cy="128" r="4"   fill="#60b898" opacity=".78"/>
      <text x="88"  y="36"  font-family="Cormorant Garamond,serif" font-style="italic" font-size="9.5" fill="#c08040" opacity=".85">Alegría</text>
      <text x="162" y="34"  font-family="Cormorant Garamond,serif" font-style="italic" font-size="9.5" fill="#c05070" opacity=".85">Amor</text>
      <text x="50"  y="100" font-family="Cormorant Garamond,serif" font-style="italic" font-size="9"   fill="#8050b0" opacity=".8">Confianza</text>
      <text x="192" y="92"  font-family="Cormorant Garamond,serif" font-style="italic" font-size="9.5" fill="#3070a0" opacity=".8">Calma</text>
      <text x="122" y="148" font-family="Cormorant Garamond,serif" font-style="italic" font-size="9.5" fill="#306060" opacity=".8">Esperanza</text>
    </svg>

    <div class="l-inst"><span class="l-dot"></span>UTN — Centro de Atención Psicológica</div>

    <div class="l-ri s" id="l-ri" onclick="goBack()">
      <span id="l-ri-t">🎓 Acceso como Estudiante</span>
      <span style="opacity:.45;font-size:.56rem"> · Cambiar</span>
    </div>

    <h1 class="l-h">Cada emoción es<br>parte de <em>quien eres</em></h1>
    <p class="l-p">Espacio de atención psicológica profesional, confidencial y humano — donde todas las dimensiones de tu experiencia emocional son comprendidas.</p>

    <div class="l-spec">
      <span class="l-sl">Espectro emocional</span>
      <div class="l-sb"></div>
      <div class="l-se"><span>Energía</span><span>Amor</span><span>Creatividad</span><span>Calma</span><span>Esperanza</span><span>Alegría</span></div>
    </div>

    <div class="l-q">
      <span class="l-qm">"</span>
      <p class="l-qt">Atender tu salud mental es un acto de valentía y de amor propio. Aquí encontrarás acompañamiento en cada paso.</p>
      <p class="l-qa">— Psic. Fanny Chimal · CEPS</p>
    </div>
  </div>

  <!-- DERECHO -->
  <div class="right">
    <div class="card">
      <!-- Mini header solo en móvil -->
      <div class="mh">
        <img src="data:image/png;base64," alt="UTN"/>
        <div><div class="mh-n">CEPS</div><div class="mh-s">Centro de Atención Psicológica · UTN</div></div>
      </div>

      <!-- ★ Logo de psicología encima del formulario ★ -->
      <div class="card-logo">
        <img src="data:image/png;base64," alt="UTN CEPS Logo"/>
      </div>

      <div class="c-strips">
        <div class="cs cs1"></div><div class="cs cs2"></div><div class="cs cs3"></div>
        <div class="cs cs4"></div><div class="cs cs5"></div><div class="cs cs6"></div>
      </div>

      <div class="c-title">Iniciar sesión</div>
      <div class="c-rtag s" id="c-rtag">🎓 Estudiante</div>
      <a class="c-chg" id="c-chg" onclick="goBack()">¿No eres estudiante? <span>Cambiar rol</span></a>

      <div class="eb" id="eb">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
        <span id="etx">Credenciales incorrectas.</span>
      </div>

      <div class="fg">
        <label id="lbl-id">Matrícula universitaria</label>
        <div class="iw">
          <input type="text" id="fid" placeholder="Ej. 2024-ISC-001" autocomplete="username"/>
          <svg class="ic" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>
        </div>
        <p class="hint" id="hint-id">Ejemplo: 2024-ISC-001</p>
      </div>

      <div class="fg">
        <label>Contraseña</label>
        <div class="iw">
          <input type="password" id="fpass" placeholder="••••••••" autocomplete="current-password"/>
          <svg class="ic" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
          <button class="ep" type="button" onclick="tgP()" aria-label="Ver contraseña">
            <svg id="ei" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
          </button>
        </div>
      </div>

      <div class="fe">
        <label class="rm"><input type="checkbox"> Recordarme</label>
        <a href="#" class="fg2">¿Olvidaste tu contraseña?</a>
      </div>

      <button class="bs" id="btn" onclick="doLogin()">
        <span class="bt">Iniciar sesión</span>
        <span class="sp"><span class="rg"></span></span>
      </button>
      <div class="cf">o</div>
      <div class="rk">¿Primera vez? <a href="#">Solicita tu acceso</a></div>
    </div>
  </div>
</div>

<script>
const DC=['#ffd080','#e87095','#b080d8','#7090d8','#60b898','#f4a261','#88c878','#c77dcc'];
const DS=[5,7,9,10,6,8,4];
function mkD(){
  const el=document.createElement('div');el.className='fd';
  const s=DS[Math.floor(Math.random()*DS.length)];
  const c=DC[Math.floor(Math.random()*DC.length)];
  const d=13+Math.random()*10;
  el.style.cssText=`width:${s}px;height:${s}px;background:${c};left:${Math.random()*100}vw;filter:blur(${Math.random()*.7}px);animation-duration:${d}s;animation-delay:${Math.random()*d}s;`;
  document.getElementById('dots').appendChild(el);
  setTimeout(()=>el.remove(),(d+4)*1000);
}
for(let i=0;i<20;i++) mkD();
setInterval(mkD,950);

let rol='usuario';

function selectRole(r){
  rol=r; const isA=r==='admin';
  document.getElementById('ws').classList.add('gone');
  requestAnimationFrame(()=>requestAnimationFrame(()=>
    document.getElementById('page').classList.add('visible')
  ));
  const $=id=>document.getElementById(id);
  if(isA){
    $('l-ri').className='l-ri a'; $('l-ri-t').textContent='🩺 Acceso como Psicóloga';
    $('c-rtag').className='c-rtag a'; $('c-rtag').textContent='🩺 Psicóloga / Admin';
    $('c-chg').innerHTML='¿No eres psicóloga? <span>Cambiar rol</span>';
    $('lbl-id').textContent='Número de empleado';
    $('hint-id').textContent='Ejemplo: EMP-001';
    $('fid').placeholder='Ej. EMP-001';
  }else{
    $('l-ri').className='l-ri s'; $('l-ri-t').textContent='🎓 Acceso como Estudiante';
    $('c-rtag').className='c-rtag s'; $('c-rtag').textContent='🎓 Estudiante';
    $('c-chg').innerHTML='¿No eres estudiante? <span>Cambiar rol</span>';
    $('lbl-id').textContent='Matrícula universitaria';
    $('hint-id').textContent='Ejemplo: 2024-ISC-001';
    $('fid').placeholder='Ej. 2024-ISC-001';
  }
  hideErr(); $('fid').value=''; $('fpass').value='';
  setTimeout(()=>$('fid').focus(),200);
}

function goBack(){
  document.getElementById('page').classList.remove('visible');
  requestAnimationFrame(()=>requestAnimationFrame(()=>
    document.getElementById('ws').classList.remove('gone')
  ));
  hideErr();
}

function tgP(){
  const inp=document.getElementById('fpass'),ico=document.getElementById('ei'),show=inp.type==='password';
  inp.type=show?'text':'password';
  ico.innerHTML=show
    ?'<path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/>'
    :'<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>';
}

function showErr(m){document.getElementById('etx').textContent=m;document.getElementById('eb').classList.add('show');}
function hideErr(){document.getElementById('eb').classList.remove('show');}

async function doLogin(){
  hideErr();
  const id=document.getElementById('fid').value.trim();
  const pw=document.getElementById('fpass').value;
  const btn=document.getElementById('btn');
  if(!id||!pw){showErr('Por favor completa todos los campos.');return;}
  btn.classList.add('ld');btn.disabled=true;
  try{
    const r=await fetch('api/auth.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identificador:id,contrasena:pw,rol})});
    const j=await r.json();
    if(j.error){showErr(j.message);btn.classList.remove('ld');btn.disabled=false;document.getElementById('fpass').value='';return;}
    btn.querySelector('.bt').textContent='¡Bienvenido/a, '+j.data.nombre.split(' ')[0]+'!';
    setTimeout(()=>{window.location.href=j.data.rol==='admin'?'index.php':'alumno.php';},900);
  }catch(e){showErr('Error de conexión. Intenta de nuevo.');btn.classList.remove('ld');btn.disabled=false;}
}
document.addEventListener('keydown',e=>{if(e.key==='Enter')doLogin();});
</script>
</body>
</html>